WITH RECURSIVE descendants AS ( SELECT u.id, u.parent_id, 1 AS depth FROM order_member_user u WHERE u.parent_id = #{userId} UNION ALL SELECT c.id, c.parent_id, p.depth + 1 FROM order_member_user c INNER JOIN descendants p ON c.parent_id = p.id ), roots AS ( SELECT u.id AS root_id, u.username AS username FROM order_member_user u WHERE u.parent_id = #{userId} ), all_desc AS ( SELECT r.root_id, u.id AS user_id, u.parent_id FROM roots r JOIN order_member_user u ON u.id = r.root_id UNION ALL SELECT ad.root_id, c.id, c.parent_id FROM all_desc ad JOIN order_member_user c ON c.parent_id = ad.user_id ), topup_stats AS ( SELECT user_id, IFNULL(SUM(CASE WHEN type = '0' THEN IFNULL(amout, 0) ELSE IFNULL(real_money, 0) END), 0) AS recharge_amount FROM order_topup WHERE status = '0'
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY user_id ), withdraw_stats AS ( SELECT user_id, IFNULL(SUM(credited_amount),0) AS withdraw_amount FROM order_withdrawal WHERE status = '0'
AND application_time BETWEEN #{startTime} AND #{endTime}
GROUP BY user_id ), commission_stats AS ( SELECT user_id, IFNULL(SUM(change_amount),0) AS commission_amount FROM order_account_change WHERE 1=1 AND `type` = '6'
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY user_id ) SELECT r.root_id AS user_id, r.username, COUNT(DISTINCT CASE WHEN ad.user_id IS NOT NULL AND ad.user_id != r.root_id THEN ad.user_id END) AS total_sub_count, (SELECT COUNT(1) FROM order_member_user d WHERE d.parent_id = r.root_id) AS direct_invite_count, (SELECT IFNULL(SUM(COALESCE(u2.balance,0)+COALESCE(u2.frozen_balance,0)),0) FROM all_desc ad2 JOIN order_member_user u2 ON u2.id = ad2.user_id WHERE ad2.root_id = r.root_id) AS total_balance, (SELECT IFNULL(SUM(ts.recharge_amount),0) FROM all_desc ad2 JOIN topup_stats ts ON ts.user_id = ad2.user_id WHERE ad2.root_id = r.root_id) AS recharge_amount, (SELECT IFNULL(SUM(cs.commission_amount),0) FROM all_desc ad2 JOIN commission_stats cs ON cs.user_id = ad2.user_id WHERE ad2.root_id = r.root_id) AS total_commission, (SELECT IFNULL(SUM(ws.withdraw_amount),0) FROM all_desc ad2 JOIN withdraw_stats ws ON ws.user_id = ad2.user_id WHERE ad2.root_id = r.root_id) AS withdraw_amount, (SELECT IFNULL(SUM(ts.recharge_amount),0) FROM all_desc ad2 JOIN topup_stats ts ON ts.user_id = ad2.user_id WHERE ad2.root_id = r.root_id) - (SELECT IFNULL(SUM(ws.withdraw_amount),0) FROM all_desc ad2 JOIN withdraw_stats ws ON ws.user_id = ad2.user_id WHERE ad2.root_id = r.root_id) AS deposit_withdraw_diff FROM roots r LEFT JOIN all_desc ad ON ad.root_id = r.root_id GROUP BY r.root_id, r.username ORDER BY r.root_id

-- 返回所有 parent_id = 0 的顶级用户，并按 username(可选) 和时间范围聚合其下级数据 WITH RECURSIVE descendants AS ( SELECT u.id, u.parent_id, 0 AS depth FROM order_member_user u WHERE u.parent_id = 0
AND u.username = #{username}
UNION ALL SELECT c.id, c.parent_id, p.depth + 1 FROM order_member_user c INNER JOIN descendants p ON c.parent_id = p.id ), subtree AS ( SELECT d.id AS user_id, p.id AS root_id FROM descendants d JOIN descendants p ON (CASE WHEN d.depth = 0 THEN d.id = p.id ELSE p.depth = 0 END) ), roots AS ( SELECT u.id AS root_id, u.username AS username FROM order_member_user u WHERE u.parent_id = 0
AND u.username = #{username}
), all_desc AS ( SELECT r.root_id, u.id AS user_id, u.parent_id FROM roots r JOIN order_member_user u ON u.id = r.root_id UNION ALL SELECT ad.root_id, c.id, c.parent_id FROM all_desc ad JOIN order_member_user c ON c.parent_id = ad.user_id ), topup_stats AS ( SELECT user_id, IFNULL(SUM(CASE WHEN type = '0' THEN IFNULL(amout, 0) ELSE IFNULL(real_money, 0) END), 0) AS recharge_amount FROM order_topup WHERE status = '0'
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY user_id ), withdraw_stats AS ( SELECT user_id, IFNULL(SUM(credited_amount),0) AS withdraw_amount FROM order_withdrawal WHERE status = '0'
AND application_time BETWEEN #{startTime} AND #{endTime}
GROUP BY user_id ), commission_stats AS ( SELECT user_id, IFNULL(SUM(change_amount),0) AS commission_amount FROM order_account_change WHERE 1=1 AND `type` = '6'
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY user_id ) SELECT r.root_id AS user_id, r.username, COUNT(DISTINCT CASE WHEN ad.user_id IS NOT NULL AND ad.user_id != r.root_id THEN ad.user_id END) AS total_sub_count, (SELECT COUNT(1) FROM order_member_user d WHERE d.parent_id = r.root_id) AS direct_invite_count, IFNULL(SUM(COALESCE(u.balance,0)+COALESCE(u.frozen_balance,0)),0) AS total_balance, IFNULL(SUM(ts.recharge_amount),0) AS recharge_amount, IFNULL(SUM(cs.commission_amount),0) AS total_commission, IFNULL(SUM(ws.withdraw_amount),0) AS withdraw_amount, IFNULL(SUM(ts.recharge_amount),0) - IFNULL(SUM(ws.withdraw_amount),0) AS deposit_withdraw_diff FROM roots r LEFT JOIN all_desc ad ON ad.root_id = r.root_id LEFT JOIN order_member_user u ON u.id = ad.user_id LEFT JOIN topup_stats ts ON ts.user_id = u.id LEFT JOIN withdraw_stats ws ON ws.user_id = u.id LEFT JOIN commission_stats cs ON cs.user_id = u.id GROUP BY r.root_id, r.username ORDER BY r.root_id
